// Geometry is shared by rendering, openings, furniture and quantities.
export function cutRect(p){if(p.shape?.type!=='l')return null;const {cutWidth:c,cutDepth:d,corner='se'}=p.shape;return {x:corner.includes('w')?0:p.length-c,y:corner.includes('n')?0:p.width-d,w:c,d};}
export function roomPolygon(p){const l=p.length,w=p.width;if(p.shape?.type!=='l')return [[0,0],[l,0],[l,w],[0,w]];const {cutWidth:c,cutDepth:d,corner='se'}=p.shape;return [[0,0],[l,0],[l,w-d],[l-c,w-d],[l-c,w],[0,w]].map(([x,y])=>[corner.includes('w')?l-x:x,corner.includes('n')?w-y:y]);}
export function wallSegments(p){const poly=roomPolygon(p),signed=poly.reduce((s,a,i)=>{const b=poly[(i+1)%poly.length];return s+a[0]*b[1]-b[0]*a[1];},0),direction=signed>=0?1:-1;return poly.map((start,i)=>{const end=poly[(i+1)%poly.length],dx=end[0]-start[0],dy=end[1]-start[1],length=Math.hypot(dx,dy),a=[Math.min(start[0],end[0]),Math.min(start[1],end[1])],b=[Math.max(start[0],end[0]),Math.max(start[1],end[1])];return {index:i,a,b,length,tangent:[(b[0]-a[0])/length,(b[1]-a[1])/length],normal:[-dy/length*direction,dx/length*direction],vertical:Math.abs(dx)<1e-8};});}
export function wallPoint(p,i,t,z=0){const s=wallSegments(p)[i];if(!s)throw Error('Стена не найдена');return [s.a[0]+s.tangent[0]*t,s.a[1]+s.tangent[1]*t,z];}
export function floorArea(p){const c=cutRect(p);return p.length*p.width-(c?c.w*c.d:0);}
export const perimeter=p=>wallSegments(p).reduce((sum,s)=>sum+s.length,0);
export function rectInside(p,x,y,w,d){const eps=1e-8;if(x<-eps||y<-eps||x+w>p.length+eps||y+d>p.width+eps)return false;const cut=cutRect(p);return !cut||!(x<cut.x+cut.w-eps&&x+w>cut.x+eps&&y<cut.y+cut.d-eps&&y+d>cut.y+eps);}
export function fitRect(p,f){const w=f.rotation%180?f.depth:f.width,d=f.rotation%180?f.width:f.depth,c=cutRect(p),clamp=(n,max)=>Math.max(0,Math.min(max,n));const xs=[clamp(f.x,p.length-w),0,p.length-w],ys=[clamp(f.y,p.width-d),0,p.width-d];if(c){xs.push(c.x-w,c.x+c.w);ys.push(c.y-d,c.y+c.d);}const candidates=[];for(const x of xs)for(const y of ys)if(rectInside(p,x,y,w,d))candidates.push({...f,x,y});candidates.sort((a,b)=>(a.x-f.x)**2+(a.y-f.y)**2-((b.x-f.x)**2+(b.y-f.y)**2));if(!candidates.length)throw Error('Мебель не помещается в выбранную форму. Уменьшите предмет или вырез.');return candidates[0];}
export function projectToWall(segment,x,y){const t=(x-segment.a[0])*segment.tangent[0]+(y-segment.a[1])*segment.tangent[1],u=Math.max(0,Math.min(segment.length,t));return {t,distance:Math.hypot(x-segment.a[0]-u*segment.tangent[0],y-segment.a[1]-u*segment.tangent[1])};}
